import { ActivityDefinition } from '../../PlaybookTypes';
/**
 * Branded so `GoBack` gets its own dedicated `ActivityFunction` overload (mirrors
 * `DecisionActivityDefinition`) — needed so `go_back_to_target_activity`/
 * `go_back_to_target_stage` can be authored as a raw lane/activity variable reference
 * (e.g. `intake.review`) and type-check without `@ts-expect-error`.
 */
export interface GoBackActivityDefinition extends ActivityDefinition {
    readonly __goBackDef: true;
    readonly __publicAccess: true;
}
/**
 * OOTB "Go Back" activity definition — restarts the playbook at an earlier stage, activity,
 * or the start of the playbook. Usable only as the terminal activity of a decision branch;
 * see go-back-validator.ts for the full set of build-time diagnostics.
 *
 * Requires the Process Automation Designer (`sn_pa_designer`) store app at version 29.3.0 or
 * later — this `sys_pd_activity_definition` record doesn't exist on earlier versions; the SDK
 * doesn't validate the installed version.
 *
 * No `activityType`: the real record's `activity_type` field is empty (no experience properties).
 *
 * DEVIATES FROM THE SHIPPED PLATFORM RECORD on two points (explicit product decision, not an
 * oversight):
 * - `enableAiAgent` is omitted (defaults to `'off'`), and no `aiAgentFieldDisplayPreferences` is
 *   set. The real record has `ai_agent_field_display_preferences` populated (AI-capable), but Go
 *   Back is a control/flow activity — AI agent support is intentionally not exposed here.
 * - `inputDisplayPreferences` sets all three inputs to `'all'`, whereas the real record's
 *   `input_display_preferences` is empty. All three inputs should be author-configurable.
 */
export declare const GoBack: GoBackActivityDefinition;
